import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long minRemainder = x;
        long numerator = 0;
        long denominator = 1;

        for (long denom = 1; denom <= n; ++denom) {
            long startA = Math.max(x * denom / y - 10, 0);
            for (int delta = 0; delta < 20; ++delta) {
                long currentA = startA + delta;
                long currentDiff = Math.abs(x * denom - currentA * y);
                if (minRemainder * denom > currentDiff * denominator) {
                    minRemainder = currentDiff;
                    numerator = currentA;
                    denominator = denom;
                } else if (minRemainder * denom == currentDiff * denominator) {
                    if (denominator > denom || (denominator == denom && numerator > currentA)) {
                        numerator = currentA;
                        denominator = denom;
                    }
                }
            }
        }
        System.out.println(numerator + "/" + denominator);
        sc.close();
    }
}
